const page = await browser.goto('https://www.ycombinator.com/companies?batch=Winter%202024');
await new Promise(r => setTimeout(r, 2000));
// look for industry filter options and their param names
const html = await browser.js(`document.body.innerText.slice(0, 2000)`);
return html;

// scroll to load more companies and collect names+descriptions
async function collect() {
  let prevCount = 0;
  for (let i=0;i<15;i++) {
    window.scrollTo(0, document.body.scrollHeight);
    await new Promise(r=>setTimeout(r,800));
    const items = document.querySelectorAll('a[href^="/companies/"]');
    if (items.length === prevCount) break;
    prevCount = items.length;
  }
  const items = Array.from(document.querySelectorAll('a[href^="/companies/"]'));
  const seen = new Set();
  const results = [];
  for (const it of items) {
    const href = it.getAttribute('href');
    if (seen.has(href)) continue;
    seen.add(href);
    results.push({href, text: it.innerText});
  }
  return results;
}
const res = await browser.js(`(${collect.toString()})()`);
return {count: res.length, sample: res.slice(0,60)};

