    return text;
  })()`);
  results[slug] = data.slice(0, 4000);
}
const fs = await import('node:fs/promises');
await fs.writeFile('company_pages.json', JSON.stringify(results, null, 2));
return Object.keys(results);

const slugs = ['retell-ai','marr-labs','basepilot','magic-hour','mathos'];
const results = {};
for (const slug of slugs) {
  await browser.goto(`https://www.ycombinator.com/companies/${slug}`);
  await new Promise(r=>setTimeout(r,1500));
  const data = await browser.js(`(function(){
    const links = Array.from(document.querySelectorAll('a[href*="linkedin.com"]')).map(a => a.href);
    return links;
  })()`);
  results[slug] = data;
}
const fs = await import('node:fs/promises');
await fs.writeFile('linkedin_links.json', JSON.stringify(results, null, 2));
return results;

